async def act(page):
    """Find and navigate to the 'Previous Post' link from the current page.

    Strategy:
    - Prefer a semantic rel="prev" anchor (common for previous-post links). Iterate
      all accessible role="link" locators and inspect their "rel" attribute.
    - When a rel=prev link is found and it has an href, navigate by assigning
      window.location.href to that href. This avoids click being blocked by overlays.
    - Fallbacks: search inside the main region for links whose visible text
      contains tokens like 'previous', 'prev', or 'older'. If found, prefer JS
      navigation via the link's href, otherwise click the link.
    - All locator indexing uses await locator.count() before .nth() to avoid
      indexing errors. DOM reads are guarded with try/except to handle transient detach.
    - The final action performs navigation and returns immediately.
    """

    # 1) Scan all accessible links for rel="prev"
    links = page.get_by_role("link")
    total = await links.count()
    for i in range(total):
        try:
            rel = await links.nth(i).get_attribute("rel")
        except Exception:
            rel = None
        if rel and "prev" in rel.lower():
            try:
                href = await links.nth(i).get_attribute("href")
            except Exception:
                href = None
            if href:
                # Navigate via JS to avoid pointer-interception by overlays
                await page.evaluate("(h) => { window.location.href = h; }", href)
                return
            else:
                # As a fallback click if no href attribute
                await links.nth(i).click()
                return

    # 2) Fallback: search inside the main region for likely-named previous links
    main = page.get_by_role("main")
    candidate_tokens = ("previous", "prev", "older")
    try:
        main_links = main.get_by_role("link")
        main_count = await main_links.count()
        for i in range(main_count):
            try:
                txt = (await main_links.nth(i).inner_text()).strip().lower()
            except Exception:
                txt = ""
            if any(tok in txt for tok in candidate_tokens):
                try:
                    href = await main_links.nth(i).get_attribute("href")
                except Exception:
                    href = None
                if href:
                    await page.evaluate("(h) => { window.location.href = h; }", href)
                    return
                else:
                    await main_links.nth(i).click()
                    return
    except Exception:
        # If main region isn't present or lookup fails, continue to page-level scan
        pass

    # 3) Final fallback: scan all page links by visible text
    for i in range(total):
        try:
            txt = (await links.nth(i).inner_text()).strip().lower()
        except Exception:
            txt = ""
        if any(tok in txt for tok in candidate_tokens):
            try:
                href = await links.nth(i).get_attribute("href")
            except Exception:
                href = None
            if href:
                await page.evaluate("(h) => { window.location.href = h; }", href)
                return
            else:
                await links.nth(i).click()
                return

    # Nothing found
    raise Exception("Previous Post link not found")

